function runtimeEntry(d){const r=runtimeFor(d);return `<div class="nu-runtime-entry"><div class="nu-panel-heading"><strong>运行参数与优化</strong>${plain('完整设置','runtime-open',d.running?'disabled':'')}</div><small>${esc(runtimeEngines[r.engine])} · ${esc(acceleratorNames[r.accelerator])}</small>${isLanguage(d)?`<small>上下文 ${r.context} · 输出 ${r.maxOutput} · ${r.thinking==='off'?'关闭思考':r.thinking==='on'?'开启思考':'模型默认思考'}</small>`:''}<div class="nl-actions">${btn('设备与引擎','runtime-open',false,`data-tab="hardware" ${d.running?'disabled':''}`)}${btn(isLanguage(d)?'缓存与加速':'生成与加速','runtime-open',false,`data-tab="${isLanguage(d)?'cache':'media'}" ${d.running?'disabled':''}`)}</div></div>`;}
function runtimeModal(o){const d=draft(),r=o.config,language=isLanguage(d),busy=!!d.running;
const f=(n,k,type='number',off=false)=>field(n,k,r[k],'runtime',type,busy||off),s=(n,k,opts,off=false)=>select(n,k,r[k],opts,'runtime',busy||off),c=(n,k,off=false)=>check(n,k,r[k],'runtime',busy||off),row=(...x)=>`<div class="nl-field-row">${x.join('')}</div>`,note=x=>`<p class="nu-runtime-help">${x}</p>`;
const tabs=language?[['generation','生成与上下文'],['cache','KV Cache'],['schedule','Prefill / Decode'],['spec','推测解码'],['hardware','设备与引擎']]:[['media','生成与加速'],['hardware','设备与引擎']];
let body='';if(o.tab==='generation')body=note('生成参数作用于本次请求；上下文包括输入、历史、模板和输出。当前模型模板的演示上限为 32,768 token。')+s('思考模式','thinking',[['default','模型默认'],['off','关闭思考'],['on','开启思考']],model(d.model)?.base!=='qwen4')+note(model(d.model)?.base==='qwen4'?'Qwen3 示例通过聊天模板切换；隐藏思考文本不会减少推理计算。':'当前模型未声明可切换思考模式。')+row(f('上下文限制（token）','context'),f('最大输出（token）','maxOutput'))+s('超过上下文时','overflow',[['reject','停止并提示'],['trim','裁剪最旧对话，保留系统消息']])+row(f('Temperature','temperature'),f('Top P','topP'))+row(f('Top K（0 = 不限制）','topK'),f('Min P','minP'))+f('重复惩罚','repeatPenalty')+f('停止词（每行一项）','stop','text')+c('流式显示输出','stream');
if(o.tab==='cache'){const opts=r.engine==='mlx'?['auto','8-bit','4-bit']:r.engine==='llama'?['auto','f16','q8_0','q4_0']:['vllm','sglang'].includes(r.engine)?['auto','fp8']:['auto'];body=note('KV Cache 保存已有 token 的中间状态；前缀缓存复用重复输入，两者与模型权重量化分别配置。')+s('KV Cache 精度','kvPrecision',opts)+f('KV 容量（token）','kvBudget')+note(r.engine==='mlx'?'低于上下文时表示旋转缓存窗口，会舍弃更早的 KV；效果需另行评测。':'当前演示要求 KV 容量覆盖上下文。实际容量还受层数、并发和显存约束。')+c('复用提示词 / 前缀缓存','prefixCache',!runtimeFeature(r,'prefix'))+s('缓存隔离范围','cacheScope',[['task','仅当前任务'],['project','当前项目']],!r.prefixCache)+note(runtimeFeature(r,'prefix')?'切换模型、tokenizer 或模板后失效；跨项目不共享。':'此引擎模板尚未开放前缀缓存配置。')+note('FP8、量化 KV 的可用格式依赖设备、模型与引擎版本。这里只保存选择，不伪造缓存命中率。');}
if(o.tab==='schedule')body=note('Prefill 处理输入；Decode 逐步生成输出。吞吐、首 token 延迟与内存占用需要一起权衡。')+f('Prefill 分块大小（token）','prefillChunk')+c('启用 Chunked Prefill 调度','chunkedPrefill',!runtimeFeature(r,'chunk'))+row(f('批处理 token 预算','batchTokens', 'number',!runtimeFeature(r,'batch')),f('Decode 并发序列数','decodeBatch','number',!runtimeFeature(r,'batch')))+note(runtimeFeature(r,'batch')?'服务引擎按预算进行连续批处理。并发增加不保证单请求更快。':'当前使用单请求模板；Prefill 步长可配置，服务批处理调度未开放。')+s('Attention 实现','attention',runtimeFeature(r,'flash')?[['auto','引擎自动选择'],['flash','Flash Attention · 需版本适配'],['sdpa','SDPA · 需版本适配']]:[['auto','引擎自动选择']])+c('CUDA Graph 捕获 / 重放','graphs',!runtimeFeature(r,'graphs'))+c('Prefill / Decode 分离式部署','splitPD',!runtimeFeature(r,'split'))+(r.splitPD?row(f('Prefill 服务地址','prefillEndpoint','text'),f('Decode 服务地址','decodeEndpoint','text'))+note('需要独立服务、KV 传输连接器和网络验证；本例尚未部署，不能应用启动。'):'');
if(o.tab==='spec')body=note('一次选择一种推测解码策略。目标模型负责验证候选 token；收益取决于草稿接受率和额外内存。')+s('推测解码策略','speculation',[['off','关闭'],['draft','普通草稿模型'],['mtp','MTP · 模型原生预测'],['dflash','DFlash · 块扩散草稿']])+(r.speculation==='mtp'?note('当前模型未声明 MTP 组件。MTP 不是任意模型都可开启的功能；需匹配原生预测头和引擎适配。'):r.speculation==='off'?note('保持标准逐 token 生成。'):`${s('草稿模型配对','draftModel',[['','选择配套组件'],[r.speculation==='dflash'?'qwen4-dflash':'qwen4-draft',r.speculation==='dflash'?'Qwen3-4B non-thinking DFlash · 示例':'Qwen3-4B 配套草稿 · 兼容流程示例']])}${btn(r.draftReady?'演示组件已准备':'模拟准备草稿组件','runtime-draft',false,!r.draftModel||r.draftReady?'disabled':'')}${note(r.speculation==='dflash'?'当前 DFlash 示例要求 Qwen3-4B + 关闭思考。需使用已适配的本地后端或服务引擎；草稿组件不会真实下载。':'实际接入必须验证 tokenizer、词表与目标模型；本例只演示配对准备流程。')}`)+(r.speculation!=='off'?row(f(r.speculation==='dflash'?'草稿块大小':'每次推测 token 数','specTokens'),s('草稿权重精度','draftPrecision',['auto','8-bit','4-bit'])):'')+note('性能检查应记录首 token 延迟、Prefill / Decode tokens/s、峰值内存与草稿接受率。当前均未实测，不提供虚构加速数字。');
if(o.tab==='hardware'){const h=hardwareCatalog[r.device];body=s('执行设备','device',Object.entries(store.settings.devices).map(([k,v])=>[k,v.name]))+s('硬件后端','accelerator',h.accelerators.map(k=>[k,acceleratorNames[k]]))+s('运行引擎','engine',enginesFor(d,r.accelerator).map(k=>[k,runtimeEngines[k]]))+note(`${h.vendor} · ${h.os} · ${h.memory}。驱动、设备型号、可用精度和算子适配需真实检测。`)+(!store.settings.devices[r.device].ready?btn('模拟检查此设备','runtime-connect'):'')+row(s('权重计算精度','precision',['auto','FP16','BF16','FP32']),f('内存使用上限（%）','memoryLimit'))+row(f('CPU 线程','cpuThreads'),f('张量并行 GPU 数','tensorParallel','number',!['vllm','sglang'].includes(r.engine)))+(r.engine==='llama'?s('GPU 卸载层数','gpuLayers',[['auto','自动'],['0','0 · CPU'],['16','16'],['32','32'],['all','全部可卸载层']]):'')+(r.engine==='coreml'?s('Core ML 计算单元策略','computeUnits',r.accelerator==='ane'?[['CPU_AND_NE','CPU + ANE'],['ALL','CPU + GPU + ANE']]:[['CPU_ONLY','仅 CPU'],['CPU_AND_GPU','CPU + GPU'],['ALL','全部可用单元']])+note('需要转换后的 Core ML 模型；系统按算子分配计算，允许 ANE 不代表整张网络一定在 ANE 上执行。'):r.accelerator==='metal'?note('MLX / MPS 使用 Apple GPU。ANE 需要选择 Core ML 路径及对应模型产物。'):r.accelerator==='rocm'?note('ROCm 支持范围取决于 AMD GPU 架构、驱动和操作系统，需逐组合检查。'):r.accelerator==='sycl'?note('oneAPI / SYCL 为 Intel GPU 路径；Intel NPU 的 OpenVINO 接入单独检查。'):'')+note('以上为设备配置示例，不扫描本机、不安装驱动，也不修改系统设置。');}
if(o.tab==='media')body=note('当前类别使用自己的生成与内存优化，不套用语言模型的 KV / MTP 参数。')+(d.kind==='audio'?s('语速','speed',['0.8','1.0','1.2'])+row(s('输出采样率','sampleRate',['16000','24000','44100','48000']),f('音频分块（毫秒）','audioChunk'))+c('分块输出音频','streamAudio')+note('流式合成、转写和变声的支持范围由具体模型适配器决定。'):s('采样调度器','scheduler',[['model-default','模型默认'],['euler','Euler · 适配示例'],['dpm','DPM++ · 适配示例']])+row(f('采样步数','sampling'),f('引导强度 CFG','cfg'))+(d.kind==='video'?row(f('生成帧数','frames'),s('生成帧率','fps',['8','16','24'])):'')+c('VAE Tiling · 分块解码','vaeTiling',r.engine!=='diffusers')+c('VAE Slicing · 分批解码','vaeSlicing',r.engine!=='diffusers'))+s('内存卸载策略','offload',[['none','不卸载'],['model','按组件卸载到 CPU'],['sequential','顺序卸载到 CPU']])+c('torch.compile 编译优化','compile',!runtimeFeature(r,'compile'))+note('降低内存占用可能增加延迟。具体算子和精度需要检查，原型不承诺所选组合的实际性能。');
return modal('运行参数与优化',`<div class="nu-runtime-head"><strong>${esc(model(d.model).name)}</strong><small>草稿修改，应用后写入当前运行配方</small></div><div class="nl-tabs nu-runtime-tabs" role="tablist" aria-label="运行设置类别">${tabs.map(([k,n])=>`<button role="tab" aria-selected="${o.tab===k}" data-action="runtime-tab" data-tab="${k}">${n}</button>`).join('')}</div><div class="nu-runtime-fields" role="tabpanel">${body}</div>${o.notice?`<div class="nl-note" role="status">${esc(o.notice)}</div>`:''}${o.errors?.length?`<div class="nl-error" role="alert">${o.errors.map(esc).join('<br>')}</div>`:''}`,btn('取消修改','close-overlay')+btn('检查并应用','runtime-apply',true,busy?'disabled':''));}
function hardwareSettings(){return `<div class="nl-note">硬件、驱动和运行引擎分别检查；这里显示可配置路径，全部为未实测的示例。</div>${select('默认运行设备','device',store.settings.device,Object.entries(store.settings.devices).map(([k,d])=>[k,d.name]),'settings')}<div class="nl-resource-list">${Object.entries(store.settings.devices).map(([id,d])=>{const h=hardwareCatalog[id];return `<div class="nl-resource-row"><div><strong>${d.name}</strong><small>${h.vendor} · ${h.os}</small><small>${h.backends} · ${h.memory}</small>${tag(d.ready?'演示连接可用 · 实机未检测':'未连接','')}</div>${btn('配置','device-detail',false,`data-id="${id}"`)}</div>`;}).join('')}</div><small>在各模型的“运行参数与优化 → 设备与引擎”中选择实际执行组合。</small>`;}
function runtimeLibraries(){return `<div class="nl-resource-list">${[['MLX-LM / MLX-VLM','Apple GPU / Metal；语言与多模态'],['llama.cpp','CPU / Metal / CUDA / HIP / SYCL / Vulkan；按构建和模型适配'],['vLLM / SGLang','服务调度、KV、Prefill / Decode、推测解码；按版本与设备检查'],['DFlash','配套草稿、本地或服务后端；按模型家族与版本检查'],['PyTorch / Transformers / Diffusers','CUDA / ROCm / MPS / CPU；生成、训练适配分开检查'],['Core ML','CPU / GPU / ANE；必须先准备转换产物'],['OpenVINO','Intel CPU / GPU / NPU；需对应产物及插件']].map(([n,x])=>`<div class="nl-resource-row"><div><strong>${n}</strong><small>${x}</small></div>${tag('待实际接入')}</div>`).join('')}</div>`;}
function runtimeHandle(action,b){if(!action.startsWith('runtime-'))return false;const d=draft(),o=store.overlay;if(action==='runtime-open'){if(d.running)return true;openOverlay({type:'runtime',tab:b.dataset.tab||(isLanguage(d)?'generation':'media'),config:clone(runtimeFor(d)),errors:[]});return true;}if(o?.type!=='runtime')return true;if(action==='runtime-tab')o.tab=b.dataset.tab;if(action==='runtime-connect'){store.settings.devices[o.config.device].ready=true;o.notice='模拟连接检查通过；没有探测真实硬件或安装驱动。';}if(action==='runtime-draft'){o.config.draftReady=true;o.notice='草稿准备流程演示完成；未下载真实组件。';}if(action==='runtime-apply'){o.errors=applyRuntime(d,o.config);if(!o.errors.length){store.overlay=null;render();showToast('运行参数已应用，下一次提交会固定到结果配方。');return true;}}overlayHost.innerHTML=overlay();return true;}
